async ({ workspace: { search, read }, git: { status, revParse } }) => {
  const [wf, pkg, skill, st, br] = await Promise.all([
    search("pi-action|NPM_CONFIG_ALLOW_GIT|allow-git", { path: ".github/workflows/pi-assistant.yml", contextLines: 4 }),
    read("package.json", { format: "raw" }),
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    status(["--short", "--branch"]),
    revParse(["--abbrev-ref", "HEAD"]),
  ]);
  const p = JSON.parse(pkg.content);
  return { wf, deps: { ...p.dependencies, ...p.peerDependencies }, skill: skill.content.slice(0, 3000), st: st.stdout, br: br.stdout };
}
